UPDATE public.inspection_base_items SET text = '17.2.11.2 카 및 승강장의 버튼, 카 및 승강장의 표시기 및 소방운전 스위치는 IP X3 이상으로 보호되어야 한다. 소방관 접근 지정 층 이외의 다른 승강장 조작반 및 승강장 위치표시기는 소방운전 스위치 작동 시 전기적으로 분리되지 않으면 IP X3 이상으로 등급으로 보호되어야 한다.', section_title = '17.2.11.2 카 및 승강장의 버튼, 카 및 승강장의 표시기 및 소방운전 스위치는 IP X3 이상으로 보호되어야 한다. 소방관 접근 지정 층 이외의 다른 승강장 조작반 및 승강장 위치표시기는 소방운전 스위치 작동 시 전기적으로 분리되지 않으면 IP X3 이상으로 등급으로 보호되어야 한다.', updated_at = now() WHERE item_id = '17.2.11.2';
UPDATE public.inspection_base_items SET text = '17.2.11.4 소방구조용 엘리베이터의 카 내부 등록버튼 위 또는 근처에 소방구조용 엘리베이터 알림 표지(그림 28)를 이용하여 선명하게 표시되어야 한다.', section_title = '17.2.11.4 소방구조용 엘리베이터의 카 내부 등록버튼 위 또는 근처에 소방구조용 엘리베이터 알림 표지(그림 28)를 이용하여 선명하게 표시되어야 한다.', updated_at = now() WHERE item_id = '17.2.11.4';
INSERT INTO public.inspection_base_items (item_id, section_id, section_title, parent_section_id, text, sort_order, is_active) VALUES ('17.2.11.3', '17', '17.2.11.3 2단계 소방운전 중에 소방구조용 엘리베이터의 운전은 카에 있는 모든 푸시 버튼에 의해 이루어져야 한다. 다른 운전시스템은 무효화되어야 한다.', '17.2.11', '17.2.11.3 2단계 소방운전 중에 소방구조용 엘리베이터의 운전은 카에 있는 모든 푸시 버튼에 의해 이루어져야 한다. 다른 운전시스템은 무효화되어야 한다.', 172113, 'true') ON CONFLICT (item_id) DO UPDATE SET text = EXCLUDED.text, section_title = EXCLUDED.section_title, updated_at = now();
